// VIOC_perf_cleanup.sqf - parche perf_cleanup de VIOC (2026-10-16). No es del autor de la mision.
// Lo carga Common\Init\Init_CommonConstants.sqf en todas las maquinas: define funciones y ajustes y lanza dos bucles,
// VIOC_PERF_fnc_serverLoop (solo servidor) y VIOC_PERF_fnc_clientHud (solo con interfaz). Ver REPORT.md del parche.
//
// Que hace (cada cosa con su parametro de lobby VIOC_PERF_*):
//  - vehiculos abandonados: Server_HandleEmptyVehicle.sqf llama a VIOC_PERF_fnc_abandoned cuando el vehiculo lleva vacio
//    el tiempo "Vehicles Recycling Delay"; se borra solo si no hay jugadores (ni su grupo) cerca, nadie de un grupo con
//    jugador lo uso en los ultimos 30 min y (segun la opcion) esta fuera de las bases. Nunca: HQ, estaticas, VIOC_KEEP,
//    VIOC_AF_parked, ni los vehiculos de apoyo (reparacion, municion, combustible, medico, salvamento) comprados por un jugador.
//  - armas en el suelo: duran lo mismo que los cuerpos (VIOC_PERF_CORPSE_TIME, 5 min por defecto). Las de un cuerpo se borran
//    con el cuerpo (Server_TrashObject.sqf); un barrido (cada la mitad de ese tiempo, entre 60 y 300 s) borra las sueltas que
//    llevan ese tiempo sin un jugador a 300 m (maximo 400 por barrido).
//  - restos de vehiculos: Server_TrashObject.sqf los borra a los VIOC_PERF_WRECK_TIME s (3 min por defecto), pero espera
//    mientras haya un jugador dentro o a menos de 100 m.
//  - cuerpos: tope de cuerpos a la vez; sobre el tope se retiran los mas viejos sin jugadores a 300 m.
//  - tope global de IA (VIOC_PERF_MAX_AI): guarniciones nuevas mas chicas (minimo 40 %) y compras de escuadras IA en espera.
//  - guarniciones de pueblo creadas repartidas en varios frames (VIOC_PERF_fnc_spawnGarrison, desde las FSM de pueblo).
//  - limpieza de arboles destruidos del pueblo repartida en celdas (VIOC_PERF_fnc_townTrees).
//  - monitor para el anfitrion (VIOC_PERF_MONITOR o, en la consola, VIOC_PERF_HUD = true;).
//
// API para otros parches (en el servidor):
//   missionNamespace getVariable ["VIOC_PERF_AI_COUNT", 0]   hombres IA vivos (allUnits sin jugadores), recuento cada 10 s
//   missionNamespace getVariable ["VIOC_PERF_AI_MAX", 1000000]   tope de IA (1000000 si el tope esta apagado)
//   [_extra] call VIOC_PERF_fnc_overBudget                    true si AI_COUNT + _extra pasa el tope (false sin tope)
//   En objetos: VIOC_KEEP = true (esta limpieza nunca lo borra), VIOC_AF_parked = true (avion estacionado de airfields).

//--- Ajustes (los parametros de lobby ya estan en missionNamespace; sin lobby valen los valores por defecto)
VIOC_PERF_VEH_KEEP_USED = 1800;  //--- s: un vehiculo usado por un jugador o su grupo no se borra hasta 30 min despues
VIOC_PERF_HOLDER_SWEEP = ((missionNamespace getVariable ["VIOC_PERF_CORPSE_TIME", 300]) / 2) max 60 min 300; //--- s entre barridos de armas en el suelo
VIOC_PERF_HOLDER_RANGE = 300;    //--- m: sin jugadores a esta distancia
VIOC_PERF_HOLDER_CAP = 400;      //--- armas borradas como maximo por barrido
VIOC_PERF_CORPSE_RANGE = 300;    //--- m: el tope de cuerpos solo retira cuerpos sin jugadores a esta distancia
VIOC_PERF_MIN_SCALE = 0.4;       //--- con la IA sobre el tope, las guarniciones nuevas no bajan de este 40 %
VIOC_PERF_SPREAD_ON = (missionNamespace getVariable ["VIOC_PERF_SPREAD", 1]) == 1;
VIOC_PERF_CONFIRM = (missionNamespace getVariable ["VIOC_PERF_DETECT_HEIGHT", 20]) != 50;
VIOC_PERF_AI_MAX = missionNamespace getVariable ["VIOC_PERF_MAX_AI", 500];
VIOC_PERF_BUDGET_ON = VIOC_PERF_AI_MAX > 0;
if !(VIOC_PERF_BUDGET_ON) then {VIOC_PERF_AI_MAX = 1000000};
if (isNil "VIOC_PERF_HUD") then {VIOC_PERF_HUD = (missionNamespace getVariable ["VIOC_PERF_MONITOR", 0]) == 1};

//--- Estado (servidor)
VIOC_PERF_AI_COUNT = 0;
VIOC_PERF_HOLDERS_N = -1;        //--- armas en el suelo vistas en el ultimo barrido (-1 = aun no hubo barrido)
VIOC_PERF_VEH_DELETED = 0;
VIOC_PERF_HOLDERS_DELETED = 0;
VIOC_PERF_CORPSES_DELETED = 0;
VIOC_PERF_SCALED = 0;            //--- guarniciones recortadas por el tope de IA
VIOC_PERF_DEFERRED = 0;          //--- compras de escuadras IA aplazadas por el tope
VIOC_PERF_PLAYER_UNITS = [];     //--- jugadores vivos y los miembros vivos de sus grupos (cada 10 s)

//=====================================================================================================================
// Tope de IA
//=====================================================================================================================
VIOC_PERF_fnc_overBudget = {
	private _extra = if (_this isEqualType [] && {count _this > 0} && {(_this select 0) isEqualType 0}) then {_this select 0} else {0};
	VIOC_PERF_BUDGET_ON && {(VIOC_PERF_AI_COUNT + _extra) > VIOC_PERF_AI_MAX}
};

//--- [grupos, plazas por grupo, pueblo] -> grupos (desde Server_SpawnTownOccupation/Resistance.sqf, sin pausas)
VIOC_PERF_fnc_scaleGroups = {
	params ["_pGroups", "_pSize", ["_pTown", objNull]];
	if (!VIOC_PERF_BUDGET_ON || {_pGroups <= 1}) exitWith {_pGroups};
	private _perGroup = (_pSize max 6) + 2; //--- +2: tripulantes de vehiculos, aprox.
	private _room = VIOC_PERF_AI_MAX - VIOC_PERF_AI_COUNT;
	private _factor = ((_room / (_pGroups * _perGroup)) max VIOC_PERF_MIN_SCALE) min 1;
	private _n = (round (_pGroups * _factor)) max 1;
	VIOC_PERF_AI_COUNT = VIOC_PERF_AI_COUNT + _n * _perGroup; //--- reserva hasta el proximo recuento (evita que varios pueblos a la vez pasen el tope)
	if (_n < _pGroups) then {
		VIOC_PERF_SCALED = VIOC_PERF_SCALED + 1;
		diag_log format ["[VIOC_PERF] guarnicion de %1 recortada de %2 a %3 grupos (IA %4 / tope %5)", _pTown getVariable ["cti_town_name", ""], _pGroups, _n, VIOC_PERF_AI_COUNT, VIOC_PERF_AI_MAX];
	};
	_n
};

//--- [grupo] -> true si la compra de escuadra IA se aplaza (desde Server_AI_PurchaseSquad.sqf, sin pausas)
VIOC_PERF_fnc_deferPurchase = {
	params [["_pGrp", grpNull, [grpNull]]];
	if (isNull _pGrp || {!([] call VIOC_PERF_fnc_overBudget)}) exitWith {false};
	private _members = units _pGrp;
	if ((_members findIf {isPlayer _x}) > -1) exitWith {false}; //--- nunca un grupo con jugador
	private _size = missionNamespace getVariable ["CTI_AI_TEAMS_GROUPSIZE", 12];
	if (({alive _x} count _members) < ceil (_size * VIOC_PERF_MIN_SCALE)) exitWith {false}; //--- equipo casi vacio: puede reponer
	VIOC_PERF_DEFERRED = VIOC_PERF_DEFERRED + 1;
	true
};

//=====================================================================================================================
// Guarniciones de pueblo repartidas en varios frames (spawn desde el estado Create de town_occupation/town_resistance.fsm)
//=====================================================================================================================
VIOC_PERF_fnc_spawnGarrison = {
	params ["_pTown", "_pSide", "_pTeams", "_pGroups", "_pPositions", "_pVar"];
	_pTown setVariable ["VIOC_PERF_creating", time];
	for "_pIdx" from 0 to (count _pGroups) - 1 do {
		private _pGrp = _pGroups select _pIdx;
		if (!isNull _pGrp) then {
			//--- un equipo cada vez con la funcion original (patrulla, HandleEmptyVehicle...); el planificador reparte el resto
			private _pNew = [_pTown, _pSide, [_pTeams select _pIdx], [_pGrp], [_pPositions select _pIdx]] call CTI_CO_FNC_CreateTownUnits;
			_pTown setVariable [_pVar, (_pTown getVariable [_pVar, []]) + _pNew]; //--- la limpieza del pueblo los ve en cuanto existen
			if (!isNull _pGrp) then {_pGrp deleteGroupWhenEmpty true}; //--- como el original createGroup [lado, true], pero ya con gente
		};
		sleep 0.2;
	};
	_pTown setVariable ["VIOC_PERF_creating", -1000];
};

//--- [pueblo]: oculta los arboles y arbustos destruidos (como el original, mismo radio) en celdas de 300 m, con pausas
VIOC_PERF_fnc_townTrees = {
	params ["_pTown"];
	if (isNull _pTown) exitWith {};
	private _c = getPosATL _pTown;
	private _r = CTI_GC_RANGE_TOWN;
	private _cells = ceil (2 * _r / 300);
	for "_ix" from 0 to _cells - 1 do {
		for "_iy" from 0 to _cells - 1 do {
			private _p = [(_c select 0) - _r + 150 + 300 * _ix, (_c select 1) - _r + 150 + 300 * _iy, 0];
			if ((_p distance2D _c) < (_r + 213)) then {
				{
					if (damage _x == 1 && {(_x distance2D _c) <= _r}) then {_x hideObjectGlobal true};
				} forEach (nearestTerrainObjects [_p, CTI_GC_TOWN_OBJECTS, 213, false, true]);
				sleep 0.05;
			};
		};
	};
};

//=====================================================================================================================
// Vehiculos abandonados
//=====================================================================================================================
VIOC_PERF_fnc_isSupport = {
	params ["_pVeh"];
	if !(isNil {_pVeh getVariable "cti_spec"}) exitWith {true};
	if ((((missionNamespace getVariable ["CTI_WEST", objNull]) getVariable ["cti_salvagers", []]) + ((missionNamespace getVariable ["CTI_EAST", objNull]) getVariable ["cti_salvagers", []])) find _pVeh > -1) exitWith {true};
	private _info = missionNamespace getVariable [typeOf _pVeh, []];
	private _script = if (_info isEqualType [] && {count _info > CTI_UNIT_SCRIPTS}) then {_info select CTI_UNIT_SCRIPTS} else {""};
	(_script isEqualType "") && {_script != ""} //--- salvager, salvager-independent, service-*
};

VIOC_PERF_fnc_inBase = {
	params ["_pVeh"];
	([missionNamespace getVariable ["CTI_WEST", objNull], missionNamespace getVariable ["CTI_EAST", objNull]] findIf {
		private _logic = _x;
		!isNull _logic && {
			private _hq = _logic getVariable ["cti_hq", objNull];
			(!isNull _hq && {(_pVeh distance2D _hq) < 400})
			|| {((_logic getVariable ["cti_structures_areas", []]) findIf {(_pVeh distance2D _x) < CTI_BASE_AREA_RANGE}) > -1}
			|| {((_logic getVariable ["cti_fobs", []]) findIf {!isNull _x && {(_pVeh distance2D _x) < 200}}) > -1}
		}
	}) > -1
};

VIOC_PERF_fnc_canDeleteVehicle = {
	params ["_pVeh", "_pMode"];
	if (!alive _pVeh || {_pVeh isKindOf "StaticWeapon"}) exitWith {false};
	if ((_pVeh getVariable ["VIOC_KEEP", false]) || {_pVeh getVariable ["VIOC_AF_parked", false]} || {!isNil {_pVeh getVariable "cti_gc_noremove"}}) exitWith {false};
	if (_pVeh in [(missionNamespace getVariable ["CTI_WEST", objNull]) getVariable ["cti_hq", objNull], (missionNamespace getVariable ["CTI_EAST", objNull]) getVariable ["cti_hq", objNull]]) exitWith {false};
	if (({alive _x} count crew _pVeh) > 0) exitWith {false};
	if ((time - (_pVeh getVariable ["VIOC_PERF_pUse", -10000000])) < VIOC_PERF_VEH_KEEP_USED) exitWith {false};
	private _owner = _pVeh getVariable ["Owner", ""];
	if (!(_owner in ["", "0"]) && {[_pVeh] call VIOC_PERF_fnc_isSupport}) exitWith {false}; //--- apoyo comprado por un jugador: nunca
	private _dist = missionNamespace getVariable ["VIOC_PERF_VEH_DIST", 1000];
	if ((VIOC_PERF_PLAYER_UNITS findIf {(_x distance _pVeh) < _dist}) > -1) exitWith {false};
	if ((allPlayers findIf {alive _x && {(_x distance _pVeh) < _dist}}) > -1) exitWith {false};
	if (_pMode >= 2 && {[_pVeh] call VIOC_PERF_fnc_inBase}) exitWith {false};
	true
};

//--- [vehiculo, demora]: desde Server_HandleEmptyVehicle.sqf (programado) cuando el vehiculo lleva vacio toda la demora
VIOC_PERF_fnc_abandoned = {
	params ["_pVeh", "_pDelay"];
	private _mode = missionNamespace getVariable ["VIOC_PERF_VEHICLES", 2];
	if (_mode < 1 || {isNull _pVeh} || {_pVeh isKindOf "StaticWeapon"}) exitWith {};
	if (!canSuspend) exitWith {_this spawn VIOC_PERF_fnc_abandoned};
	while {alive _pVeh} do {
		if (({alive _x} count crew _pVeh) > 0) exitWith {[_pVeh, _pDelay] spawn CTI_SE_FNC_HandleEmptyVehicle}; //--- volvio a tener gente: se vigila de nuevo desde cero
		if ([_pVeh, _mode] call VIOC_PERF_fnc_canDeleteVehicle) exitWith {
			{if (!alive _x) then {deleteVehicle _x}} forEach (crew _pVeh); //--- muertos que sigan dentro
			deleteVehicle _pVeh;
			VIOC_PERF_VEH_DELETED = VIOC_PERF_VEH_DELETED + 1;
		};
		sleep 60;
	};
};

//--- [objeto] -> true si es un resto de vehiculo con un jugador dentro o a menos de 100 m (Server_TrashObject.sqf espera)
VIOC_PERF_fnc_wreckBusy = {
	params [["_pObj", objNull, [objNull]]];
	!isNull _pObj && {_pObj isKindOf "AllVehicles"} && {(allPlayers findIf {alive _x && {(_x distance _pObj) < 100}}) > -1}
};

//--- vehiculos en los que esta un jugador o alguien de un grupo con jugador (cada 10 s): marca de uso
VIOC_PERF_fnc_markPlayerVehicles = {
	private _list = [];
	{
		{
			if (alive _x) then {
				_list pushBackUnique _x;
				private _v = objectParent _x;
				if (!isNull _v) then {_v setVariable ["VIOC_PERF_pUse", time]};
			};
		} forEach (units group _x);
	} forEach allPlayers;
	VIOC_PERF_PLAYER_UNITS = _list;
};

//=====================================================================================================================
// Armas en el suelo y cuerpos
//=====================================================================================================================
//--- [cuerpo]: borra las armas tiradas a 5 m del cuerpo (desde Server_TrashObject.sqf y el tope de cuerpos)
VIOC_PERF_fnc_bodyHolders = {
	params [["_pBody", objNull, [objNull]]];
	if (isNull _pBody || {(missionNamespace getVariable ["VIOC_PERF_HOLDERS", 1]) <= 0}) exitWith {};
	if ((allPlayers findIf {alive _x && {(_x distance _pBody) < 50}}) > -1) exitWith {}; //--- un jugador cerca (quiza recogiendo): las deja para el barrido
	private _n = 0;
	{
		if !(_x getVariable ["VIOC_KEEP", false]) then {deleteVehicle _x; _n = _n + 1};
	} forEach (nearestObjects [_pBody, ["WeaponHolderSimulated", "WeaponHolder"], 5]);
	VIOC_PERF_HOLDERS_DELETED = VIOC_PERF_HOLDERS_DELETED + _n;
};

VIOC_PERF_fnc_holderSweep = {
	//--- mismo tiempo que los cuerpos; se descuenta medio barrido porque un arma puede llevar hasta un barrido en el suelo antes de verse
	private _age = if ((missionNamespace getVariable ["VIOC_PERF_HOLDERS", 1]) > 0) then {(CTI_GC_DELAY_MAN - VIOC_PERF_HOLDER_SWEEP / 2) max 60} else {0};
	if (_age <= 0 && {!(missionNamespace getVariable ["VIOC_PERF_HUD", false])}) exitWith {};
	private _holders = (allMissionObjects "WeaponHolderSimulated") + (allMissionObjects "WeaponHolder");
	VIOC_PERF_HOLDERS_N = count _holders;
	if (_age <= 0) exitWith {};
	private _plist = allPlayers select {alive _x};
	private _n = 0;
	{
		if (_n >= VIOC_PERF_HOLDER_CAP) exitWith {};
		private _h = _x;
		if (!isNull _h) then {
			private _t = _h getVariable "VIOC_PERF_hT";
			if (isNil "_t") then {
				_h setVariable ["VIOC_PERF_hT", time]; //--- primera vez que se ve
			} else {
				if ((time - _t) > _age && {!(_h getVariable ["VIOC_KEEP", false])} && {(_plist findIf {(_x distance _h) < VIOC_PERF_HOLDER_RANGE}) == -1}) then {
					deleteVehicle _h;
					_n = _n + 1;
				};
			};
		};
	} forEach _holders;
	VIOC_PERF_HOLDERS_N = VIOC_PERF_HOLDERS_N - _n;
	VIOC_PERF_HOLDERS_DELETED = VIOC_PERF_HOLDERS_DELETED + _n;
};

VIOC_PERF_fnc_corpseCap = {
	private _cap = missionNamespace getVariable ["VIOC_PERF_CORPSE_CAP", 120];
	if (_cap <= 0) exitWith {};
	private _dead = allDeadMen;
	private _excess = (count _dead) - _cap;
	if (_excess <= 0) exitWith {};
	private _plist = allPlayers select {alive _x};
	private _cand = [];
	{
		private _b = _x;
		if (isNull objectParent _b && {(_plist findIf {(_x distance _b) < VIOC_PERF_CORPSE_RANGE}) == -1}) then {
			_cand pushBack [_b getVariable ["VIOC_PERF_gcT", time], _forEachIndex]; //--- marca del recolector (update_garbage_collector.fsm); solo numeros para sort
		};
	} forEach _dead;
	_cand sort true; //--- los mas viejos primero
	private _max = _excess min 60;
	private _n = 0;
	{
		if (_n >= _max) exitWith {};
		private _b = _dead select (_x select 1);
		if (!isNull _b) then {
			private _g = group _b;
			[_b] call VIOC_PERF_fnc_bodyHolders;
			deleteVehicle _b; //--- su Server_TrashObject dormido vera el objeto nulo y terminara solo
			if (!isNull _g && {(count units _g) == 0} && {isNil {_g getVariable "cti_gc_noremove"}} && {!(_g call CTI_CO_FNC_IsGroupPlayable)}) then {deleteGroup _g};
			_n = _n + 1;
		};
	} forEach _cand;
	VIOC_PERF_CORPSES_DELETED = VIOC_PERF_CORPSES_DELETED + _n;
};

//=====================================================================================================================
// Monitor
//=====================================================================================================================
VIOC_PERF_fnc_publishStats = {
	private _ai = allUnits select {!isPlayer _x};
	private _g = allGroups;
	private _v = vehicles;
	private _towns = missionNamespace getVariable ["CTI_Towns", []];
	VIOC_PERF_STATS = [
		round diag_fps, round diag_fpsMin,                                                          // 0-1 servidor
		count _ai, west countSide _ai, east countSide _ai, resistance countSide _ai,                // 2-5
		count _g, {side _x == west} count _g, {side _x == east} count _g, {side _x == resistance} count _g, // 6-9
		{_x isKindOf "LandVehicle" && {!(_x isKindOf "StaticWeapon")}} count _v,                    // 10
		{_x isKindOf "Air"} count _v,                                                               // 11
		{_x isKindOf "StaticWeapon"} count _v,                                                      // 12
		{alive _x && {(_x isKindOf "LandVehicle" && {!(_x isKindOf "StaticWeapon")}) || {_x isKindOf "Air"} || {_x isKindOf "Ship"}} && {({alive _x} count crew _x) == 0}} count _v, // 13 vacios
		count allDeadMen,                                                                           // 14
		VIOC_PERF_HOLDERS_N,                                                                        // 15
		{(_x getVariable ["cti_town_resistance_active", false]) || {_x getVariable ["cti_town_occupation_active", false]}} count _towns, // 16
		VIOC_PERF_AI_COUNT, if (VIOC_PERF_BUDGET_ON) then {VIOC_PERF_AI_MAX} else {0},             // 17-18
		diag_activeScripts,                                                                         // 19 [spawn, execVM, exec, execFSM]
		round (time / 60),                                                                          // 20
		VIOC_PERF_VEH_DELETED, VIOC_PERF_HOLDERS_DELETED, VIOC_PERF_CORPSES_DELETED, VIOC_PERF_SCALED, VIOC_PERF_DEFERRED // 21-25
	];
	publicVariable "VIOC_PERF_STATS";
};

VIOC_PERF_fnc_clientHud = {
	if (!hasInterface) exitWith {};
	private _shown = false;
	while {true} do {
		if (missionNamespace getVariable ["VIOC_PERF_HUD", false]) then {
			_shown = true;
			private _s = missionNamespace getVariable ["VIOC_PERF_STATS", []];
			if (count _s < 26) then {
				hintSilent "VIOC monitor: esperando datos del servidor (VIOC_PERF_HUD = true; tambien en el servidor)";
			} else {
				private _sc = _s select 19;
				hintSilent parseText format [
					"<t size='0.9' align='left'><t color='#a5c4ff'>VIOC monitor</t> (min %1)<br/>FPS %2 (min %3) | servidor %4 (min %5)<br/>IA %6 (W %7 / E %8 / I %9)<br/>tope IA %10 (cuenta %11)<br/>grupos %12 (W %13 / E %14 / I %15)<br/>vehiculos tierra %16, aire %17, estaticas %18, vacios %19<br/>cuerpos %20 | armas suelo %21<br/>pueblos activos %22<br/>scripts spawn %23 execVM %24 fsm %25<br/>borrados: veh %26, armas %27, cuerpos %28<br/>guarniciones recortadas %29, compras IA aplazadas %30</t>",
					_s select 20, round diag_fps, round diag_fpsMin, _s select 0, _s select 1,
					_s select 2, _s select 3, _s select 4, _s select 5,
					if ((_s select 18) > 0) then {_s select 18} else {"no"}, _s select 17,
					_s select 6, _s select 7, _s select 8, _s select 9,
					_s select 10, _s select 11, _s select 12, _s select 13,
					_s select 14, if ((_s select 15) < 0) then {"?"} else {_s select 15},
					_s select 16,
					_sc select 0, _sc select 1, _sc select 3,
					_s select 21, _s select 22, _s select 23,
					_s select 24, _s select 25
				];
			};
		} else {
			if (_shown) then {_shown = false; hintSilent ""};
		};
		sleep 5;
	};
};

//=====================================================================================================================
// Bucle del servidor (cada 10 s)
//=====================================================================================================================
VIOC_PERF_fnc_serverLoop = {
	if (!isServer) exitWith {};
	waitUntil {sleep 1; !isNil "CTI_Init_Server"};
	private _nextCorpse = time + 30;
	private _nextHolders = time + 120;
	while {!(missionNamespace getVariable ["CTI_GameOver", false])} do {
		VIOC_PERF_AI_COUNT = {!isPlayer _x} count allUnits;
		call VIOC_PERF_fnc_markPlayerVehicles;
		if (time > _nextCorpse) then {_nextCorpse = time + 30; call VIOC_PERF_fnc_corpseCap};
		if (time > _nextHolders) then {_nextHolders = time + VIOC_PERF_HOLDER_SWEEP; call VIOC_PERF_fnc_holderSweep};
		if (missionNamespace getVariable ["VIOC_PERF_HUD", false]) then {
			if (VIOC_PERF_HOLDERS_N < 0) then {_nextHolders = 0}; //--- con el monitor, el primer recuento de armas cuanto antes
			call VIOC_PERF_fnc_publishStats;
		};
		sleep 10;
	};
};

if (isServer) then {[] spawn VIOC_PERF_fnc_serverLoop};
if (hasInterface) then {[] spawn VIOC_PERF_fnc_clientHud};

class VIOC_PERF_VEHICLES {
	title = "VIOC rendimiento: Borrar vehiculos abandonados (vacios mas que 'Vehicles Recycling Delay'; nunca el HQ, ni con jugadores cerca, ni los usados por tu grupo en 30 min, ni tus camiones de apoyo)";
	values[] = {0,1,2};
	texts[] = {"Nunca (original)","Lejos de jugadores","Lejos de jugadores y fuera de bases"};
	default = 2;
};
class VIOC_PERF_VEH_DIST {
	title = "VIOC rendimiento: Distancia minima a jugadores (y a su grupo) para borrar un vehiculo abandonado";
	values[] = {500,1000,1500,2000};
	texts[] = {"500 m","1000 m","1500 m","2000 m"};
	default = 1000;
};
class VIOC_PERF_WRECK_TIME {
